 34	describe("infrastructure operator command boundaries", () => {
 35	  it(
 36	    "preserves bounded blocked output across command and Layer failures",
 37	    () => {
 38	      const sharedPath = "tmp/proof/operator-command-boundary.json";
 39	      const cases = [
 40	        {
 41	          script: "generate-adoption-manifest.ts",
