 86	            BUNDJIL_ALCHEMY_STATE_ACCESS_KEY_ID: "",
 87	            BUNDJIL_ALCHEMY_STATE_SECRET_ACCESS_KEY: "",
 88	            BUNDJIL_INFRASTRUCTURE_DRIFT_STAGE: "prod",
 89	          },
 90	          output: "stateConfigurationInvalid",
 91	        },
 92	      ] as const;
 93	
 94	      for (const fixture of cases) {
 95	        const result = runCommand(fixture.script, fixture.environment);
 96	        expect(result.exitCode).not.toBe(0);
 97	        expect(result.output).toContain(fixture.output);
 98	        expect(result.output).not.toContain("ConfigError");
 99	      }
