101	      const previewConfiguration = runCommand(
102	        "preview-configuration-drift.ts",
103	        {
104	          BUNDJIL_PREVIEW_CONFIGURATION_AUTHORITY_PATH: "",
105	          BUNDJIL_PREVIEW_VERCEL_PROJECT_ID: "",
106	          BUNDJIL_PREVIEW_VERCEL_TEAM_ID: "",
107	        }
108	      );
109	      expect(previewConfiguration.exitCode).not.toBe(0);
110	      expect(previewConfiguration.output.trim()).toBe('{"status":"blocked"}');
111	      expect(previewConfiguration.output).not.toContain(
112	        "VercelPreviewConfigurationAuthorityError"
113	      );
114	      expect(previewConfiguration.output).not.toContain("ConfigError");
115	      expect(previewConfiguration.output).not.toContain(packageRoot);
116	      expect(previewConfiguration.output).not.toContain("at <anonymous>");
117	
118	      const automaticProduction = runCommand("automatic-production.ts", {
119	        BUNDJIL_PRODUCTION_SOURCE_SHA: undefined,
120	      });
121	      expect(automaticProduction.exitCode).not.toBe(0);
122	      expect(automaticProduction.output.trim()).toBe(
123	        '{"status":"blocked","category":"configuration","operation":null,"project":null,"reason":null,"retry":null}'
124	      );
125	      expect(automaticProduction.output).not.toContain(
126	        "ProductionDeploymentError"
127	      );
128	      expect(automaticProduction.output).not.toContain("ConfigError");
129	      expect(automaticProduction.output).not.toContain(packageRoot);
130	      expect(automaticProduction.output).not.toContain("at <anonymous>");
131	    },
