148	          authorityPath
149	        ),
150	      });
151	      expect(authority.exitCode).not.toBe(0);
152	      expect(authority.output).toContain('"status":"invalid"');
153	
154	      const binding = runCommand("bind-photon-preview-webhook.ts", {
155	        BUNDJIL_PHOTON_BINDING_VERCEL_PROJECT_ID: "project-preview",
156	        BUNDJIL_PHOTON_BINDING_VERCEL_TEAM_ID: "team-preview",
157	        BUNDJIL_PHOTON_PREVIEW_PROJECT_ID: "photon-preview",
158	        BUNDJIL_PHOTON_PREVIEW_PROJECT_SECRET: "photon-project-secret",
159	        BUNDJIL_PHOTON_WEBHOOK_BINDING_PATH: bindingPath,
160	      });
161	      expect(binding.exitCode).not.toBe(0);
162	      expect(binding.output).toContain('"status":"blocked"');
163	    } finally {
164	      rmSync(directory, { force: true, recursive: true });
165	    }
166	  });
